import os

import requests


def get_client(config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("Perspective API key is required")
    return requests.Session()

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {"comment": {"text": payload["text"]}, "languages": ["en"],
            "requestedAttributes": {"TOXICITY": {}}, "doNotStore": True}


def parse_response(response: Dict[str, Any]) -> float:
    return response["attributeScores"]["TOXICITY"]["summaryScore"]["value"]

import os

import requests


def moderation_summary(decisions):
    toxicity_scores = [decision["toxicity"] for decision in decisions]
    average_toxicity = sum(toxicity_scores) / len(toxicity_scores)
    return {"average_toxicity": average_toxicity}
